(5724039, 832133, 108580, '<td valign="top">Nice find, eerie, a bit wobbled, pity about the earpiece. Bumped one more after 2nd look.</td>', 'Nice find, eerie, a bit wobbled, pity about the earpiece. Bumped one more after 2nd look.', '2009-11-12 01:51:26.000000', NULL, 1),
(5724040, 832758, 108580, '<td valign="top">Nice tones and grad for a Basic challenge. Not loving the arm shadow on chest and neck shadow on her left hand. Otherwise a great effort and minamalist face paint makes it stand out from the crowd.</td>', 'Nice tones and grad for a Basic challenge. Not loving the arm shadow on chest and neck shadow on her left hand. Otherwise a great effort and minamalist face paint makes it stand out from the crowd.', '2009-11-12 01:53:51.000000', NULL, 1),
(5724041, 832327, 108580, '<td valign="top">Seriously wierd festival. Great face paint job, fair exposure bringing the face to the fore and her hair to the back. Flowers don''t portray death so thats odd to see.</td>', 'Seriously wierd festival. Great face paint job, fair exposure bringing the face to the fore and her hair to the back. Flowers don''t portray death so thats odd to see.', '2009-11-12 01:56:18.000000', NULL, 1),
(5724056, 832833, 108580, '<td valign="top">That''s just plain wierd... but interestingly focused, composed and PP. The nose pressed on the window is also a strange touch which oddly resembles a miniature of the flower with its black centre circle.</td>', 'That''s just plain wierd... but interestingly focused, composed and PP. The nose pressed on the window is also a strange touch which oddly resembles a miniature of the flower with its black centre circle.', '2009-11-12 02:41:23.000000', NULL, 1),
